/**
 * Trial-state colour palette — Experiment 1 alignment (2026-05-09).
 *
 * Round 1 (the manuscript at SUBMITTED-Dec-20-2025/XLM-S-25-01387.pdf,
 * "There was a white (RGB 255, 255, 255) or gray (RGB 211, 211, 211)
 * background, changing from trial to trial randomly, with large letter
 * stimuli presented in the opposite shade") used a per-trial light/gray
 * background with stimuli rendered in black. The follow-up experiment
 * carries that palette forward across all 5 trial types so the within-
 * subjects comparison to Round 1 is a clean visual replication rather
 * than a contrast inversion.
 *
 *   - Per-trial background: WHITE (#FFFFFF) or LIGHT-GRAY (#D3D3D3),
 *     counterbalanced 50/50 within every block of every trial type.
 *   - Pattern overlay: complementary shade (gray on white, white on
 *     gray) so the pattern reads as a figure on every trial.
 *   - Stimuli (dots, stars, question-mark glyph, rotation arrow):
 *     BLACK on every trial regardless of background shade. Round 1
 *     used `RGBA 0,0,0,~0.87`; we use solid black for the SVG fills
 *     since they sit on opaque white/gray backdrops.
 *   - Bull's-eye ring + fixation centre dot: dim DARK, low alpha so
 *     they read as fixation aids rather than competing stimuli on the
 *     light backdrop.
 *
 * The non-trial UI surfaces (calibration, instructions, demos, rest,
 * questionnaire, upload, completion, welcome) keep their existing dark
 * theme — only the per-trial visual area flips to white/gray. The flip
 * happens at the trial-start gate's `on_finish` and is reverted by the
 * next gate's `on_load`, so participants see the dark UI gate first,
 * arm the trial, and the page then flips for the entire trial body
 * (arrow cue → imagination → pattern phase → encoding → retention →
 * probes → ITI). See `page-background.js` for the flip mechanism.
 */

export const BACKGROUND_SHADES = Object.freeze(['white', 'gray']);

export const BACKGROUND_FILLS = Object.freeze({
  white: '#FFFFFF',
  gray: '#D3D3D3',
});

/* Pattern fill complements the background. On a WHITE-bg trial the
 * pattern is gray on white; on a GRAY-bg trial it is white on gray.
 * This mirrors Round 1 ("large letter stimuli presented in the opposite
 * shade") and keeps the pattern readable as figure-on-ground regardless
 * of the trial's background shade. */
export const PATTERN_FILLS_BY_BG = Object.freeze({
  white: '#D3D3D3',
  gray: '#FFFFFF',
});

/* Stimulus colour for dots, stars, and the central '?' / probe glyph
 * during trial state. Round 1 used RGBA 0,0,0,~0.87; we use solid
 * black (no alpha) because our stimuli sit on opaque backgrounds and
 * the alpha would only smear the edge against the page. */
export const STIMULUS_BLACK = '#000000';

/* Bull's-eye ring + fixation centre-dot colours during trial state.
 * Same alpha scheme as the dark-theme defaults (0.229 / 0.35) but on
 * black ink so they read on a light backdrop. The dim alpha keeps the
 * ring as a fixation aid rather than a competing stimulus. */
export const BULLSEYE_COLOUR_DARK = 'rgba(0, 0, 0, 0.229)';
export const FIXATION_MARK_COLOUR_DARK = 'rgba(0, 0, 0, 0.85)';

/* Trial-counter overlay text colour during trial state — dark text on
 * the light page. Mirrors the dark-theme `rgba(255,255,255,0.6)` alpha
 * but inverted to ink. */
export const TRIAL_COUNTER_TEXT_DARK = 'rgba(0, 0, 0, 0.6)';

export function isValidBackgroundShade(shade) {
  return shade === 'white' || shade === 'gray';
}
